import itertools, sys

def is_costas(p):
    n=len(p)
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            dr=p[j]-p[i]
            dc=j-i
            if (dr,dc) in seen:
                return False
            seen.add((dr,dc))
    return True

n=8
for perm in itertools.permutations(range(n)):
    if is_costas(perm):
        print(perm)
        break
